    let damage = 0;
    let throwAttack = 0;

    for(let i in ab) {
        H -= ab[i][1];
        throwAttack++;

        if(H <= 0) {
            console.log(throwAttack);
            return;
        }
    }

    const directAttack = Math.ceil(H / aMax);

    console.log(throwAttack + directAttack);
}
